/// The object a feed action is about (`ModuleFeedViewHelper::getData`).
#[derive(Clone, Copy, PartialEq, Eq)]
enum Feedable {
    Label,
    Address,
    ContactInformation,
    Pet,
    Note,
    Goal,
    MoodTrackingEvent,
}

impl Feedable {
    fn of(action: &str) -> Option<Feedable> {
        Some(match action {
            "label_assigned" | "label_removed" => Feedable::Label,
            "address_created" | "address_updated" | "address_destroyed" => Feedable::Address,
            "contact_information_created" | "contact_information_updated" | "contact_information_destroyed" => {
                Feedable::ContactInformation
            }
            "pet_created" | "pet_updated" | "pet_destroyed" => Feedable::Pet,
            "note_created" | "note_updated" | "note_destroyed" => Feedable::Note,
            "goal_created" | "goal_updated" | "goal_destroyed" => Feedable::Goal,
            "mood_tracking_event_added" | "mood_tracking_event_updated" | "mood_tracking_event_deleted" => {
                Feedable::MoodTrackingEvent
            }
            _ => return None,
        })
    }

    /// `feedable_type` of the object (the Eloquent class name).
    fn class(self) -> &'static str {
        match self {
            Feedable::Label => "App\\Models\\Label",
            Feedable::Address => "App\\Models\\Address",
            Feedable::ContactInformation => "App\\Models\\ContactInformation",
            Feedable::Pet => "App\\Models\\Pet",
            Feedable::Note => "App\\Models\\Note",
            Feedable::Goal => "App\\Models\\Goal",
            Feedable::MoodTrackingEvent => "App\\Models\\MoodTrackingEvent",
        }
    }
}

impl FeedItem {
    /// `ModuleFeedViewHelper::data` of feed items shown in `vault_id`, in
    /// their order: the author (with their contact in the vault), the
    /// contact's hover card and the object of the action, null when it was
    /// deleted since. Items whose contact no longer exists are left out.
    pub async fn load_many<C: ConnectionTrait>(
        db: &C,
        vault_id: Uuid,
        items: Vec<contact_feed_items::Model>,
    ) -> ApiResult<Vec<FeedItem>> {
        let authors = Authors::load(db, vault_id, items.iter().filter_map(|i| i.author_id)).await?;
        let contact_ids: HashSet<Uuid> = items.iter().map(|i| i.contact_id).collect();
        let mut contacts: HashMap<Uuid, contacts::Model> = HashMap::new();
        if !contact_ids.is_empty() {
            for c in contacts::Entity::find()
                .filter(contacts::Column::Id.is_in(contact_ids.into_iter().collect::<Vec<_>>()))
                .all(db)
                .await?
            {
                contacts.insert(c.id, c);
            }
        }
        let items: Vec<_> = items.into_iter().filter(|i| contacts.contains_key(&i.contact_id)).collect();
        let cards = ContactCard::load_many(db, items.iter().map(|i| contacts[&i.contact_id].clone()).collect()).await?;
        let today = Utc::now().date_naive();

        let mut out = Vec::with_capacity(items.len());
        for (item, contact) in items.into_iter().zip(cards) {
            let kind = Feedable::of(&item.action);
            let object_id =
                kind.and_then(|k| item.feedable_id.filter(|_| item.feedable_type.as_deref() == Some(k.class())));
            let mut f = FeedItem {
                id: item.id,
                author: authors.summary(item.author_id),
                contact,
                description: item.description,
                label: None,
                address: None,
                contact_information: None,
                pet: None,
                note: None,
                goal: None,
                mood_tracking_event: None,
                created_at: ts(item.created_at),
                action: item.action,
            };
            match kind {
                Some(Feedable::Label) => f.label = Some(feed_label(db, object_id).await?),
                Some(Feedable::Address) => f.address = Some(feed_address(db, object_id).await?),
                Some(Feedable::ContactInformation) => {
                    f.contact_information = Some(feed_contact_information(db, object_id).await?)
                }
                Some(Feedable::Pet) => f.pet = Some(feed_pet(db, object_id).await?),
                Some(Feedable::Note) => f.note = Some(feed_note(db, vault_id, object_id).await?),
                Some(Feedable::Goal) => f.goal = Some(feed_goal(db, object_id, today).await?),
                Some(Feedable::MoodTrackingEvent) => {
                    f.mood_tracking_event = Some(feed_mood_tracking_event(db, object_id).await?)
                }
                None => {}
            }
            out.push(f);
        }
        Ok(out)
    }
}

