async fn feed_goal<C: ConnectionTrait>(db: &C, id: Option<Id>, today: NaiveDate) -> ApiResult<Option<Goal>> {
    let Some(g) = (match id {
        Some(id) => goals::Entity::find_by_id(id).one(db).await?,
        None => None,
    }) else {
        return Ok(None);
    };
    let mut days: Vec<NaiveDate> = streaks::Entity::find()
        .filter(streaks::Column::GoalId.eq(g.id))
        .order_by_asc(streaks::Column::HappenedAt)
        .all(db)
        .await?
        .into_iter()
        .map(|s| s.happened_at.0.date())
        .collect();
    days.dedup();
    let (max_streak, current_streak) = streak_data(&days, today);
    Ok(Some(Goal {
        id: g.id,
        contact_id: g.contact_id,
        name: g.name,
        active: g.active,
        max_streak,
        current_streak,
        last_7_days: (0..7)
            .rev()
            .map(|back| {
                let date = today - Duration::days(back);
                GoalLast7Day { date, has_streak: days.contains(&date) }
            })
            .collect(),
        created_at: ts(g.created_at),
        updated_at: ts(g.updated_at),
    }))
}

/// `GoalHelper::getStreakData` with the Q6 fix (as listContactGoals
/// computes it), on the goal's streak days (ascending, distinct):
/// `(max_streak, current_streak)`, the longest run of consecutive days (0
/// without streaks) and the run ending on the latest streak when that is
/// `today` (else 0).
fn streak_data(days: &[NaiveDate], today: NaiveDate) -> (i64, i64) {
    let (mut max, mut run) = (0, 0);
    let mut previous: Option<NaiveDate> = None;
    for day in days {
        run = if previous.and_then(|p| p.succ_opt()) == Some(*day) { run + 1 } else { 1 };
        max = std::cmp::max(max, run);
        previous = Some(*day);
    }
    (max, if days.last() == Some(&today) { run } else { 0 })
}

