/// A PATCH value: the sent one (trimmed, empty as null), else the stored one.
fn patched(sent: Option<Option<String>>, stored: &Option<String>) -> Option<String> {
    match sent {
        Some(v) => clean(v),
        None => stored.clone(),
    }
}

#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/contacts/{contact_id}",
    operation_id = "updateContact",
    tag = "Contacts",
    summary = "Update a contact's names, flags or template",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path)),
    request_body = ContactUpdate,
    responses((status = 200, description = "The updated contact.", body = Contact), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R043", "R048", "R051", "R052", "R056"])), ("x-services" = json!(["UpdateContact", "ToggleArchiveContact", "ToggleFavoriteContact", "ToggleQuickFactModule", "UpdateContactTemplate"])))
)]
pub async fn update_contact(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id)): Path<(Uuid, Uuid)>,
    Json(body): Json<ContactUpdate>,
) -> ApiResult<Json<Contact>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Edit).await?;
    let contact = contact_in_vault(&state.db, vault_id, contact_id).await?;
    let (account_id, author_id) = (id.user.account_id, id.user.id);

    let names_sent = body.first_name.is_some()
        || body.last_name.is_some()
        || body.middle_name.is_some()
        || body.nickname.is_some()
        || body.maiden_name.is_some()
        || body.prefix.is_some()
        || body.suffix.is_some()
        || body.gender_id.is_some()
        || body.pronoun_id.is_some();
    let first_name = match body.first_name {
        Some(f) => clean(Some(f)),
        None => contact.first_name.clone(),
    };
    let last_name = patched(body.last_name, &contact.last_name);
    let middle_name = patched(body.middle_name, &contact.middle_name);
    let nickname = patched(body.nickname, &contact.nickname);
    let maiden_name = patched(body.maiden_name, &contact.maiden_name);
    let prefix = patched(body.prefix, &contact.prefix);
    let suffix = patched(body.suffix, &contact.suffix);
    let sent_gender = body.gender_id.map(|g| g.map(Id));
    let sent_pronoun = body.pronoun_id.map(|p| p.map(Id));
    let template_id = body.template_id.map(Id);

    let mut v = Validator::new();
    if names_sent {
        v.required("first_name", &first_name);
        check_names(
            &mut v,
            [
                ("first_name", first_name.as_deref()),
                ("last_name", last_name.as_deref()),
                ("middle_name", middle_name.as_deref()),
                ("nickname", nickname.as_deref()),
                ("maiden_name", maiden_name.as_deref()),
                ("prefix", prefix.as_deref()),
                ("suffix", suffix.as_deref()),
            ],
        );
    }
    check_account_rows(&state, &mut v, account_id, sent_gender.flatten(), sent_pronoun.flatten(), template_id).await?;
    v.finish()?;

    let tx = state.db.begin().await?;
    let mut current = contact;
    if names_sent {
        current = UpdateContact {
            account_id,
            vault_id,
            author_id,
            contact_id,
            first_name: first_name.unwrap_or_default(),
            last_name,
            middle_name,
            nickname,
            maiden_name,
            gender_id: sent_gender.unwrap_or(current.gender_id),
            pronoun_id: sent_pronoun.unwrap_or(current.pronoun_id),
            suffix,
            prefix,
        }
        .execute(&tx)
        .await?;
    }
    if body.listed.is_some_and(|l| l != current.listed) {
        current = ToggleArchiveContact { account_id, vault_id, author_id, contact_id }.execute(&tx).await?;
    }
    if let Some(favorite) = body.is_favorite
        && favorite != is_favorite(&tx, author_id, &current).await?
    {
        current = ToggleFavoriteContact { account_id, vault_id, author_id, contact_id }.execute(&tx).await?;
    }
    if body.show_quick_facts.is_some_and(|s| s != current.show_quick_facts) {
        ToggleQuickFactModule { account_id, vault_id, author_id, contact_id }.execute(&tx).await?;
    }
    if let Some(template_id) = template_id {
        UpdateContactTemplate { account_id, vault_id, author_id, contact_id, template_id }.execute(&tx).await?;
    }
    tx.commit().await?;
    let contact = contact_in_vault(&state.db, vault_id, contact_id).await?;
    Ok(Json(Contact::load(&state.db, author_id, contact).await?))
}

