async fn quick_fact_of(state: &AppState, contact_id: Uuid, quick_fact_id: Id) -> ApiResult<quick_facts::Model> {
    quick_facts::Entity::find_by_id(quick_fact_id)
        .filter(quick_facts::Column::ContactId.eq(contact_id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)
}

/// `'content' => 'required|string|max:255'`.
fn check_content(v: &mut Validator, content: &Option<String>) {
    if v.required("content", content) {
        v.max_len("content", content.as_deref(), 255);
    }
}

#[derive(Debug, Default, Deserialize, IntoParams)]
#[into_params(parameter_in = Query)]
pub struct ListContactQuickFactsQuery {
    /// Only the facts of this quick fact template.
    #[param(value_type = Option<i64>)]
    pub vault_quick_facts_template_id: Option<Id>,
}

#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/contacts/{contact_id}/quick-facts",
    operation_id = "listContactQuickFacts",
    tag = "Contacts",
    summary = "List a contact's quick facts",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path), ListContactQuickFactsQuery),
    responses((status = 200, description = "Quick facts, oldest first; not paginated.", body = QuickFactList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R046"])), ("x-services" = json!([])))
)]
pub async fn list_contact_quick_facts(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id)): Path<(Uuid, Uuid)>,
    Query(query): Query<ListContactQuickFactsQuery>,
) -> ApiResult<Json<QuickFactList>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let contact = contact_in_vault(&state.db, vault_id, contact_id).await?;
    let mut select = quick_facts::Entity::find().filter(quick_facts::Column::ContactId.eq(contact.id));
    if let Some(template_id) = query.vault_quick_facts_template_id {
        // R046: `$contact->vault->quickFactsTemplateEntries()->findOrFail($templateId)`.
        vault_quick_facts_templates::Entity::find_by_id(template_id)
            .filter(vault_quick_facts_templates::Column::VaultId.eq(vault_id))
            .one(&state.db)
            .await?
            .ok_or_else(ApiError::not_found)?;
        select = select.filter(quick_facts::Column::VaultQuickFactsTemplateId.eq(template_id));
    }
    let rows = select.order_by_asc(quick_facts::Column::Id).all(&state.db).await?;
    Ok(Json(QuickFactList { data: rows.into_iter().map(Into::into).collect() }))
}

